typedef unsigned long компьютер_Үгэн;
static компьютер_Үгэн 동적기억공간[8192];static unsigned 사용량;
void 자바실패(void){const char Бичвэр[]="AOT runtime error\n";бичих_файл_өгөгдөл(2,Бичвэр,sizeof(Бичвэр)-1);사용자호출(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(компьютер_Үгэн *давхцал_Санах_ой,int *깊이,компьютер_Үгэн утга){if(*깊이<0||*깊이>=128)자바실패();давхцал_Санах_ой[(*깊이)++]=утга;}
компьютер_Үгэн 자바꺼내기(компьютер_Үгэн *давхцал_Санах_ой,int *깊이){if(*깊이<=0||*깊이>128)자바실패();return давхцал_Санах_ой[--*깊이];}
компьютер_Үгэн 자바배열(int 개수){if(개수<0||(unsigned)개수+1>8192-사용량)자바실패();компьютер_Үгэн*자료위치=동적기억공간+사용량;사용량+=개수+1;자료위치[0]=개수;return (компьютер_Үгэн)자료위치;}
компьютер_Үгэн *자바색인(компьютер_Үгэн объект_Толь_лавлах,int 개수){компьютер_Үгэн*자료위치=(компьютер_Үгэн*)объект_Толь_лавлах;if(!자료위치||개수<0||(компьютер_Үгэн)개수>=자료위치[0])자바실패();return 자료위치+개수+1;}
int 자바길이(компьютер_Үгэн объект_Толь_лавлах){if(!объект_Толь_лавлах)자바실패();return *(компьютер_Үгэн*)объект_Толь_лавлах;}
int 자바나누기(int х_координат,int 세로좌표,int 나머지){if(!세로좌표)자바실패();if(х_координат==(-2147483647-1)&&세로좌표==-1)return 나머지?0:х_координат;return 나머지?х_координат%세로좌표:х_координат/세로좌표;}
static unsigned урт_утга(const char*мөр_өгөгдөл){unsigned 개수=0;if(!мөр_өгөгдөл)자바실패();while(мөр_өгөгдөл[개수])개수++;return 개수;}
void 자바출력(компьютер_Үгэн 자료위치,int 수치,int 줄바꿈){
    if(수치){char 둘째값[16];unsigned 개수=0;int утга=(int)자료위치;unsigned 부호없는값=утга<0?0-(unsigned)утга:утга;do{둘째값[개수++]='0'+부호없는값%10;부호없는값/=10;}while(부호없는값);if(утга<0)둘째값[개수++]='-';while(개수)бичих_файл_өгөгдөл(1,둘째값+--개수,1);}
    else{const char*мөр_өгөгдөл=자료위치?(const char*)자료위치:"null";бичих_файл_өгөгдөл(1,мөр_өгөгдөл,урт_утга(мөр_өгөгдөл));}if(줄바꿈)бичих_файл_өгөгдөл(1,"\n",1);
}
компьютер_Үгэн 자바파일쓰기(компьютер_Үгэн ЗАМ,компьютер_Үгэн утга){const char*мөр_өгөгдөл=(const char*)утга;unsigned 개수=урт_утга(мөр_өгөгдөл);int файл_барих=нээх_файл((const char*)ЗАМ,쓰기전용|없으면만들기|내용비우기,0600);if(файл_барих<0)자바실패();int 반환값=бичих_файл_өгөгдөл(файл_барих,мөр_өгөгдөл,개수);хаах_файл(файл_барих);if(반환값!=(int)개수)자바실패();return 0;}
компьютер_Үгэн 자바파일읽기(компьютер_Үгэн ЗАМ){int файл_барих=нээх_файл((const char*)ЗАМ,зөвхөн_унших_утга,0);if(файл_барих<0)자바실패();int 개수=файл_хэмжээ(файл_барих);if(개수<0||개수>16384||(unsigned)(개수+8)/8>8192-사용량)자바실패();char*자료위치=(char*)(동적기억공간+사용량);사용량+=(개수+8)/8;int 반환값=파일자료읽기(файл_барих,자료위치,개수);хаах_файл(файл_барих);if(반환값!=개수)자바실패();자료위치[개수]=0;return (компьютер_Үгэн)자료위치;}
